styles:
/* ═══════════════════════════════════════════════════════════════
       Personalización — taller de temas.
       Solo layout de la página: ni un color literal, todo sale de los
       tokens --is-* para que la propia página respete la marca activa.
       ═══════════════════════════════════════════════════════════════ */

    .tw-seeds {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
      gap: 1rem;
      align-items: start;

      & .tw-seed-name { grid-column: 1 / -1; max-width: 22rem; }
    }

    .tw-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.75rem;
      margin-top: 0.9rem;
    }

    /* ── Doble panel: dark y light a la vez ───────────────────────── */
    .tw-panels {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(21rem, 1fr));
      gap: 1.15rem;

      @media (max-width: 720px) {
        grid-template-columns: minmax(0, 1fr);
      }
    }

    /* El panel ES el ámbito del tema: lleva .theme-dark/.theme-light y
       encima los tokens generados como propiedades inline. Todo lo que
       cuelga dentro —incluidos los shadow roots de los is-*— los hereda. */
    .tw-panel {
      display: block;
      padding: 1.1rem;
      border-radius: var(--is-radius);
      border: 1px solid var(--is-border);
      background: var(--is-bg);
      color: var(--is-text);
      box-shadow: var(--is-shadow);
      min-width: 0;

      & .tw-panel__head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.6rem;
        margin: 0 0 0.9rem;
        padding-bottom: 0.55rem;
        border-bottom: 1px solid var(--is-border-soft);
        font-size: 0.72rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--is-text-soft);
      }

      & .tw-panel__body {
        display: flex;
        flex-direction: column;
        gap: 0.95rem;
      }

      & .tw-row {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.55rem;
      }

      & .tw-grid2 {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
        gap: 0.7rem;
      }

      & .tw-note {
        margin: 0;
        font-size: 0.8rem;
        line-height: 1.5;
        color: var(--is-text-soft);
      }
    }

    /* Muestras de la rampa generada */
    .tw-ramp {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(4.5rem, 1fr));
      gap: 0.4rem;
      margin-top: 0.9rem;

      & .tw-chip {
        display: grid;
        gap: 0.15rem;
        padding: 0.5rem 0.4rem;
        border-radius: var(--is-radius-sm);
        border: 1px solid var(--is-border);
        font-family: var(--is-mono);
        font-size: 0.62rem;
        text-align: center;

        & b { font-size: 0.6rem; letter-spacing: 0.04em; opacity: 0.85; }
        & span { font-size: 0.62rem; }
      }
    }

    /* ── Bloque de exportación: barra + salida, una sola pieza ────── */
    .tw-export {
      margin-top: 1rem;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg-elev);
      box-shadow: var(--is-shadow);
      overflow: hidden;
    }

    .tw-export__bar {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.6rem;
      padding: 0.6rem 0.7rem;
      border-bottom: 1px solid var(--is-border-soft);
      background: color-mix(in srgb, var(--is-bg-elev) 60%, transparent);

      & .tw-export__file {
        display: inline-flex;
        align-items: center;
        gap: 0.35rem;
        font-family: var(--is-mono);
        font-size: 0.78rem;
        color: var(--is-text);
      }

      & .tw-export__meta {
        display: inline-flex;
        align-items: center;
        gap: 0.35rem;
        font-family: var(--is-mono);
        font-size: 0.7rem;
        color: var(--is-text-soft);
      }

      /* Empuja copiar/descargar al extremo: la barra se lee de izquierda
         (qué archivo es) a derecha (qué hago con él). */
      & .tw-export__spacer { flex: 1 1 auto; min-width: 0.5rem; }
    }

    /* La salida ES un `pre.code`: la colorea CodeMirror como cualquier otro
       snippet, y el observer del highlighter la repinta en cada `is-input`
       del picker. Aquí solo queda encajarla en la tarjeta. */
    .tw-output {
      margin: 0;
      max-height: 26rem;
      border: 0;
      border-radius: 0;
      box-shadow: none;
      font-size: 0.76rem;
    }
    .tw-persist-hint {
      margin: 0.5rem 0 0;
      font-size: 0.75rem;
      color: var(--is-text-dim);
    }

blocks.code:
/* marca: sirve a dark y light por igual */
[data-palette="contapyme"] {
  --is-color-brand: #1a6eb0;
  --is-accent: #1a6eb0;
  --is-accent-bg: rgb(26 110 176 / 12%);
  --is-brand-soft: rgb(26 110 176 / 18%);
  --is-focus: #1a6eb0;
}

/* superficies: dependen de la PAREJA (tema, paleta) */
.theme-dark[data-palette="contapyme"]  { --is-bg: #0a0e14; --is-border: #273040; }
.theme-light[data-palette="contapyme"] { --is-bg: #fff;    --is-border: #ccc; }
